// The narration, cut to the picture.
//
// `tools/voice.json` is the script: one line a beat, and the second the beat falls at. The picture is the one
// `tools/demo.json` recorded, and its scene times are read from `.demo/demo-times.json`, which the recorder writes, so a
// line can be checked against the scene it speaks over rather than against a second count kept by hand.
//
//   npm run dub
//
// The lines are generated by `voice`, which is a local Kokoro model and not a service: nothing leaves the machine and a
// re-run is the same audio. Each line is placed at its own second, and a line that would run into the next is pushed
// back until it does not, so a script that grew a word cannot make two voices talk over each other.

import { execFileSync, spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const script = JSON.parse(readFileSync(join(ROOT, 'tools/voice.json'), 'utf8'));
const times = JSON.parse(readFileSync(join(ROOT, '.demo/demo-times.json'), 'utf8'));

/** How long a file plays, in seconds, which is what decides whether a line collides with the next. */
function secondsOf(path) {
  return Number(
    execFileSync('ffprobe', [
      '-v', 'error',
      '-show_entries', 'format=duration',
      '-of', 'default=nw=1:nk=1',
      path,
    ], { encoding: 'utf8' }).trim(),
  );
}

/** The scene a second falls in, which is what a line is checked against rather than trusted blindly. */
function sceneAt(at) {
  return times.scenes.find((scene) => scene.from <= at && at < scene.to) ?? null;
}

const work = mkdtempSync(join(tmpdir(), 'theoros-voice-'));
try {
  const placed = [];
  let floor = 0;
  for (const [index, line] of script.lines.entries()) {
    const file = join(work, `line${index + 1}.wav`);
    execFileSync('voice', [
      'say',
      '-q',
      '-v', script.voice,
      '-s', String(script.speed),
      '-o', file,
      line.text,
    ], { stdio: ['ignore', 'ignore', 'inherit'] });
    const length = secondsOf(file);
    const at = Math.max(line.at, floor);
    const scene = sceneAt(at);
    if (!scene) throw new Error(`line ${index + 1} falls outside every scene at ${at}s`);
    if (at > line.at + 0.01) console.warn(`dub: line ${index + 1} moved to ${at.toFixed(2)}s to clear the one before`);
    placed.push({ file, at, length, text: line.text, scene: scene.text });
    floor = at + length + 0.25;
  }

  const last = placed[placed.length - 1];
  for (const line of placed) {
    console.log(`${line.at.toFixed(2)}s +${line.length.toFixed(2)}s  ${line.text}`);
  }
  if (last.at + last.length > times.seconds) {
    throw new Error(`the narration runs to ${(last.at + last.length).toFixed(2)}s and the picture ends at ${times.seconds.toFixed(2)}s`);
  }

  mkdirSync(dirname(join(ROOT, script.out)), { recursive: true });
  const delays = placed.map((line) => `[${placed.indexOf(line) + 1}]adelay=${Math.round(line.at * 1000)}:all=1[a${placed.indexOf(line) + 1}]`);
  const mixed = placed.map((_, index) => `[a${index + 1}]`).join('');
  const rendered = spawnSync('ffmpeg', [
    '-y',
    '-i', join(ROOT, '.demo/skene-theoros.mp4'),
    ...placed.flatMap((line) => ['-i', line.file]),
    '-filter_complex', `${delays.join(';')};${mixed}amix=inputs=${placed.length}:normalize=0,loudnorm=I=-16:TP=-1.5:LRA=11,apad[a]`,
    '-map', '0:v',
    '-map', '[a]',
    '-c:v', 'copy',
    '-c:a', 'aac',
    '-b:a', '192k',
    // The voice is 24 kHz mono, and an AAC stream at that rate cannot take a bitrate this large.
    '-ar', '48000',
    '-ac', '2',
    '-shortest',
    '-movflags', '+faststart',
    join(ROOT, script.out),
  ], { encoding: 'utf8' });
  if (rendered.status !== 0) throw new Error(`ffmpeg could not write the dub:\n${rendered.stderr}`);

  console.log(`dub: ${script.out}, ${placed.length} lines over ${times.seconds.toFixed(2)}s`);
} finally {
  rmSync(work, { recursive: true, force: true });
}
